package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin:     func(r *http.Request) bool { return true },
}

type FileStore struct {
	mu       sync.RWMutex
	basePath string
	index    map[string]string
}

func NewFileStore(base string) *FileStore {
	os.MkdirAll(base, 0750)
	return &FileStore{
		basePath: base,
		index:    make(map[string]string),
	}
}

func (fs *FileStore) generateToken() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func (fs *FileStore) sanitizePath(userPath string) string {
	cleaned := filepath.Clean(userPath)
	cleaned = strings.ReplaceAll(cleaned, "..", "")
	cleaned = strings.TrimPrefix(cleaned, "/")
	return cleaned
}

func (fs *FileStore) resolveUploadPath(filename string) string {
	safe := fs.sanitizePath(filename)
	return filepath.Join(fs.basePath, safe)
}

func (fs *FileStore) handleListRequest(conn *websocket.Conn, dirPath string) error {
	fs.mu.RLock()
	defer fs.mu.RUnlock()

	requested := fs.sanitizePath(dirPath)
	targetDir := filepath.Join(fs.basePath, requested)

	// Security check: verify resolved path is within basePath using symlink-safe resolution
	absTarget, err := filepath.EvalSymlinks(targetDir)
	if err != nil {
		return conn.WriteMessage(websocket.TextMessage, []byte("error: invalid path"))
	}
	absBase, err := filepath.EvalSymlinks(fs.basePath)
	if err != nil {
		return conn.WriteMessage(websocket.TextMessage, []byte("error: internal error"))
	}

	if !strings.HasPrefix(absTarget+"/", absBase+"/") {
		return conn.WriteMessage(websocket.TextMessage, []byte("error: access denied"))
	}

	entries, err := os.ReadDir(targetDir)
	if err != nil {
		return conn.WriteMessage(websocket.TextMessage, []byte("error: cannot read directory"))
	}

	var listing strings.Builder
	listing.WriteString(fmt.Sprintf("listing:%s\n", requested))
	for _, entry := range entries {
		info, _ := entry.Info()
		if info != nil {
			listing.WriteString(fmt.Sprintf("%s\t%d\t%s\n", entry.Name(), info.Size(), info.ModTime().Format("2006-01-02")))
		}
	}

	return conn.WriteMessage(websocket.TextMessage, []byte(listing.String()))
}

func (fs *FileStore) handleUpload(conn *websocket.Conn, filename string, data []byte) error {
	fs.mu.Lock()
	defer fs.mu.Unlock()

	safe := fs.sanitizePath(filename)
	// Additional check: no path separators allowed in upload filenames
	if strings.Contains(safe, string(filepath.Separator)) {
		return conn.WriteMessage(websocket.TextMessage, []byte("error: subdirectories not allowed"))
	}

	destPath := filepath.Join(fs.basePath, safe)

	// Verify final path resolves within basePath
	absBase, _ := filepath.EvalSymlinks(fs.basePath)
	absDest := filepath.Join(absBase, safe)
	if !strings.HasPrefix(absDest+"/", absBase+"/") && absDest != absBase {
		return conn.WriteMessage(websocket.TextMessage, []byte("error: access denied"))
	}

	f, err := os.Create(destPath)
	if err != nil {
		return conn.WriteMessage(websocket.TextMessage, []byte("error: create failed"))
	}
	defer f.Close()

	if _, err := io.Copy(f, strings.NewReader(string(data))); err != nil {
		return conn.WriteMessage(websocket.TextMessage, []byte("error: write failed"))
	}

	token, err := fs.generateToken()
	if err != nil {
		return conn.WriteMessage(websocket.TextMessage, []byte("error: token generation failed"))
	}
	fs.index[token] = destPath

	return conn.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf("ok:%s", token)))
}

func (fs *FileStore) wsHandler(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		msgType, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}
		if msgType != websocket.TextMessage {
			continue
		}

		parts := strings.SplitN(string(msg), "|", 3)
		if len(parts) < 2 {
			conn.WriteMessage(websocket.TextMessage, []byte("error: malformed request"))
			continue
		}

		cmd := parts[0]
		switch cmd {
		case "LIST":
			fs.handleListRequest(conn, parts[1])
		case "UPLOAD":
			if len(parts) < 3 {
				conn.WriteMessage(websocket.TextMessage, []byte("error: missing data"))
				continue
			}
			fs.handleUpload(conn, parts[1], []byte(parts[2]))
		default:
			conn.WriteMessage(websocket.TextMessage, []byte("error: unknown command"))
		}
	}
}

func main() {
	store := NewFileStore("./uploads")
	http.HandleFunc("/ws", store.wsHandler)
	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
